import { Component, OnInit, OnDestroy, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import { HttpClient, HttpParams } from '@angular/common/http';

export interface Client {
  clientId: number;
  numeroClient: string;
  nom: string;
  prenom: string;
  telephone: string;
  email: string;
  adresseInstallation: string;
}

export interface Reclamation {
  id: number;
  reference: string;
  statut: 'OUVERTE' | 'EN_COURS_IA' | 'RESOLUE_PAR_IA' | 'ESCALADEE_SUPPORT' | 'CLOTUREE';
  priorite: 'BASSE' | 'NORMALE' | 'HAUTE';
  description: string;
  categorieCode: string;
  categorieLibelle: string;
  sousCategorieCode: string;
  sousCategorieLibelle: string;
  dateCreation: string;
  dateMiseAJour: string;
}

export interface ReclamationItem {
  reclamation: Reclamation;
  client: Client;
}

export interface NotificationItem {
  id: number;
  message: string;
  time: string;
  unread: boolean;
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

const API_URL = 'http://localhost:8080/api/support';

@Component({
  selector: 'app-zone',
standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
   templateUrl: './zone.component.html',
   styleUrls: ['./zone.component.css']
})


export class ZoneComponent implements OnInit, OnDestroy {

  private http = inject(HttpClient);
  private readonly url = `${API_URL}/reclamations`;

  agentName: string = 'Karim Mansour';
  agentRole: string = 'Agent Support Senior';

  currentTimeFormatted: string = '';
  private clockInterval: any;

  showNotifications: boolean = false;
  notifications: NotificationItem[] = [
    { id: 1, message: 'Nouvelle réclamation urgente (Fibre Optique)', time: 'Il y a 5 min', unread: true },
    { id: 2, message: 'Technicien assigné à la Zone #04', time: 'Il y a 20 min', unread: true }
  ];

  searchTerm: string = '';
  selectedStatusFilter: string = 'TOUS';

  // Stocke directement le tableau reçu du backend
  items: ReclamationItem[] = [];
  loading: boolean = false;
  errorMessage: string = '';

  isClientModalOpen: boolean = false;
  selectedClient: Client | null = null;
  selectedReclamationRef: string = '';

  ngOnInit(): void {
    this.updateClock();
    this.clockInterval = setInterval(() => this.updateClock(), 1000);
    this.chargerReclamations();
  }

  ngOnDestroy(): void {
    if (this.clockInterval) clearInterval(this.clockInterval);
  }

  // Appel direct sans pagination
  chargerReclamations(): void {
    this.loading = true;
    this.http.get<ReclamationItem[]>(this.url).subscribe({
      next: (data) => {
        this.items = data || [];
        this.loading = false;
      },
      error: (err) => {
        console.error('Erreur chargement réclamations', err);
        this.errorMessage = 'Impossible de contacter le serveur Hexabyte.';
        this.loading = false;
      }
    });
  }

  openClientDetails(client: Client, reference: string): void {
    this.selectedClient = client;
    this.selectedReclamationRef = reference;
    this.isClientModalOpen = true;
  }

  closeClientModal(): void {
    this.isClientModalOpen = false;
    this.selectedClient = null;
  }

  private updateClock(): void {
    const now = new Date();
    let hours = now.getHours();
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';

    hours = hours % 12;
    hours = hours ? hours : 12;
    this.currentTimeFormatted = `${String(hours).padStart(2, '0')}:${minutes}:${seconds} ${ampm}`;
  }

  get unreadNotificationsCount(): number {
    return this.notifications.filter(n => n.unread).length;
  }

  markAllAsRead(): void {
    this.notifications.forEach(n => n.unread = false);
  }

  get filteredItems(): ReclamationItem[] {
    return this.items.filter(item => {
      const rec = item.reclamation;
      const cli = item.client;
      const search = this.searchTerm.toLowerCase();

      const matchesSearch = 
        cli.nom.toLowerCase().includes(search) ||
        cli.prenom.toLowerCase().includes(search) ||
        cli.numeroClient.toLowerCase().includes(search) ||
        rec.reference.toLowerCase().includes(search) ||
        rec.sousCategorieLibelle.toLowerCase().includes(search);

      const matchesStatus = 
        this.selectedStatusFilter === 'TOUS' || 
        rec.statut === this.selectedStatusFilter;

      return matchesSearch && matchesStatus;
    });
  }
}
